const BattleLabUI={render(){
 const box=$('labSetup'),planning=state.phase==='orders',c=state.countries[active];
 $('departmentObjectives').hidden=true;
 box.innerHTML=`<h2>Build a battle test</h2><p>Four widely separated kingdoms. Switch Country above to control each side. Add any troop to any territory for free, ready immediately. Place opponents on the same territory to compare them without travelling.</p><p><strong>${esc(c.name)} · land income each round:</strong> ${stockText(BattleLab.income(state,active))}. All goes directly to Military; army meals use 1 food per regiment. No civilian feeding or research bonuses.</p>${planning?`<div class="row"><label>Troop <select id="labType">${options(Object.entries(R.types).map(([id,t])=>[id,t.name]),'spears')}</select></label><label>Number <input id="labCount" type="number" min="1" max="24" value="1"></label><label>Health <input id="labHealth" type="number" min="1" max="100" value="100"></label><label>Equipment <select id="labGear"></select></label><label>Place at <select id="labAt">${options(state.territories.map(t=>[t.id,`${t.id+1} · ${t.name} · ${country(t.owner)}`]),selected)}</select></label><button id="labAdd" class="primary">Add test troops</button></div><div class="row"><label>Movement bonus <select id="labMove">${options([[2,'Base troop speeds'],[3,'Each troop +1 territory'],[4,'Each troop +2 territories']],c.movement)}</select></label><button id="labClear">Clear this country’s troops</button><button id="labRemember">Save test setup</button><button id="labReplay">Replay saved setup</button></div><div id="labRoster">${living().filter(u=>u.country===active).map(u=>`<p>${R.types[u.type].name} #${u.id} · ${u.hp} health · territory ${u.territory+1} <button data-remove="${u.id}">Remove</button></p>`).join('')}</div>`:'<p>Army setup opens again next planning phase. Use Restore previous phase to revise the current test.</p><button id="labReplay">Replay saved setup</button>'}`;
 if(planning){
  const gears=()=>{$('labGear').innerHTML=options(R.development.gearNames[$('labType').value].map((v,i)=>[i,v]),0);};gears();$('labType').onchange=gears;
  $('labAdd').onclick=()=>{const args=[active,Number($('labAt').value),$('labType').value,Number($('labCount').value),Number($('labHealth').value),Number($('labGear').value)];change(s=>BattleLab.add(s,...args),'Test troops placed, ready now. Switch countries to set up the opposing force.');};
  $('labMove').onchange=e=>{const movement=Number(e.target.value);change(s=>{s.countries[active].movement=movement;s.units.filter(u=>u.country===active).forEach(u=>u.order=null);},'Movement updated; this country’s movement orders cleared.');};
  $('labClear').onclick=()=>ask('Remove all troops belonging to '+c.name+'?',()=>change(s=>{s.units=s.units.filter(u=>u.country!==active);},'Country army cleared.'));
  box.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>change(s=>{R.detach(s,Number(b.dataset.remove));s.units=s.units.filter(u=>u.id!==Number(b.dataset.remove));},'Test troop removed.'));
  $('labRemember').onclick=()=>{try{GameStorage.setItem(KEY+'-setup',JSON.stringify(state));notice('Test setup saved. Replay restores every country, army and resource balance.');}catch{notice('Storage full. Use Download game to keep this setup.');}};
 }
 $('labReplay').onclick=()=>{const raw=GameStorage.getItem(KEY+'-setup');if(!raw){notice('Save a test setup during planning first.');return;}ask('Restore the saved test setup for all four countries?',()=>{try{const next=BattleLab.open(JSON.parse(raw));GameStorage.setItem(KEY+'-previous',JSON.stringify(state));state=next;active=0;selected=state.countries[0].capital??0;save();render();notice('Test setup restored.');}catch(e){notice(e.message);}});};
}};
